package com.fixmer.mared.technology.server.setup;
import com.fixmer.genesis.technology.server.remote.*;
import com.fixmer.mared.technology.server.firstlaunch.FirstLaunchServer58;
import net.minecraft.client.Minecraft;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** One screen's asynchronous work. Closing it invalidates callbacks; only explicit Apply can start handoff. */
public final class BootstrapService76 {
 private final AtomicBoolean busy=new AtomicBoolean(),cancelled=new AtomicBoolean();private volatile String phase="IDLE",error="";private volatile Bootstrap76.State state;private volatile RemoteClient69.Preview preview;private volatile RemoteClient69.Download download;private volatile byte[] recovery;private RemoteClient69 client;private String game,endpoint,mode;private UUID account;private boolean preparing,armed;private volatile long bytes;
 public boolean bound(String address,String url,String auth){try{return RemoteOffer69.gameAddress(address).equals(game)&&RemoteOffer69.base(url).equals(endpoint)&&auth.equals(mode);}catch(Exception bad){return false;}}
 public boolean running(){return preparing||armed;}public boolean busy(){return busy.get();}public String phase(){return preparing?RemoteApplyService70.phase():phase;}public String error(){return error;}public Bootstrap76.State state(){return state;}public RemoteClient69.Preview preview(){return preview;}public boolean recovery(){return recovery!=null;}public long bytes(){return bytes;}public boolean armed(){return armed;}
 private interface Work{void run()throws Exception;}
 private void work(String stage,Work operation){if(cancelled.get()||!busy.compareAndSet(false,true))return;phase=stage;error="";Thread t=new Thread(()->{try{operation.run();}catch(Exception bad){String code=bad.getMessage();error=bad instanceof java.io.InterruptedIOException?"CANCELLED":code!=null&&code.matches("(?:BOOTSTRAP76|RECOVERY76|REMOTE70)_[A-Z0-9_]{1,60}")?code:RemoteUpdateCli69.safeCode(bad);phase="FAILED";}finally{busy.set(false);}},"genesis-bootstrap76");t.setDaemon(true);t.start();}
 private void checkOpen()throws Exception{if(cancelled.get())throw new java.io.InterruptedIOException("REMOTE_CANCELLED");}
 public void inspect(String address,String url,String auth){if(preparing)return;Minecraft mc=Minecraft.getInstance();Path profile=mc.gameDirectory.toPath().toAbsolutePath().normalize();List<Path> loaded=FirstLaunchServer58.loaded();String neo=FirstLaunchServer58.version("neoforge"),name=mc.getUser().getName();UUID online=mc.getUser().getProfileId();
  work("CHECKING",()->{state=null;preview=null;download=null;recovery=null;game=RemoteOffer69.gameAddress(address);endpoint=RemoteOffer69.base(url);mode=auth;if(!Set.of("ONLINE","LOCAL_OFFLINE").contains(mode)||mode.equals("LOCAL_OFFLINE")&&!Set.of("localhost","127.0.0.1","[::1]").contains(game.substring(0,game.lastIndexOf(':'))))throw new java.io.IOException("REMOTE70_OFFLINE");account=mode.equals("ONLINE")?online:UUID.nameUUIDFromBytes(("OfflinePlayer:"+name).getBytes(StandardCharsets.UTF_8));var found=Bootstrap76.inspect(game,endpoint,"1.21.1",neo,cancelled::get);if(found.phase().equals("UNAVAILABLE"))throw new java.io.IOException("BOOTSTRAP76_UNAVAILABLE");client=RemoteClient69.bootstrap(RemoteService69.root(),"1.21.1",neo,found.offer().release());var p=client.inspect(game,endpoint,cancelled::get);if(!Arrays.equals(found.offer().encode(),p.offer().encode()))throw new java.io.IOException("BOOTSTRAP76_CHANGED");checkOpen();state=found;preview=p;if(!p.trusted()){phase="UNTRUSTED";return;}recovery=Recovery76.find(RemoteService69.root(),found,account);checkOpen();phase=recovery!=null?"RECOVERY":found.phase().equals("READY")&&!BootstrapRuntime76.complete()?"RUNTIME_PENDING":Bootstrap76.runtimeMatchesStartup(found,profile,loaded,"1.21.1",neo,BootstrapRuntime76.snapshot())?"MATCH":"UPDATE";});
 }
 public void trust(){if(preview==null||!phase.equals("UNTRUSTED")||preparing)return;var expected=state;var p=preview;work("TRUSTING",()->{var current=Bootstrap76.inspect(game,endpoint,"1.21.1",p.offer().neoforge(),cancelled::get);Bootstrap76.same(expected,current);checkOpen();client.trust(p);ServerDirectory76.save(RemoteService69.root(),game,endpoint,mode);phase="RECHECK";});}
 public void download(){if(preview==null||!preview.trusted()||!Set.of("UPDATE","RECOVERY").contains(phase)||preparing)return;var expected=state;work("DOWNLOADING",()->{bytes=0;var current=Bootstrap76.inspect(game,endpoint,"1.21.1",preview.offer().neoforge(),cancelled::get);Bootstrap76.same(expected,current);var d=client.download(preview,cancelled::get,n->bytes=n);checkOpen();var fresh=Bootstrap76.inspect(game,endpoint,"1.21.1",preview.offer().neoforge(),cancelled::get);Bootstrap76.same(expected,fresh);Bootstrap76.mark(d,fresh);download=d;state=fresh;phase="DOWNLOADED";});}
 public void apply(){if(busy()||cancelled.get()||download==null||!phase.equals("DOWNLOADED")||RemoteApplyService70.busy())return;if(RemoteApplyService70.startBootstrap76(mode,download,recovery)){preparing=true;phase="PREPARING";}else phase="APPLY_REFUSED";}
 public void tick(){if(preparing&&!armed){String now=RemoteApplyService70.phase();if(now.equals("READY")&&RemoteApplyService70.busy()){armed=true;RemoteApplyService70.command("ARM");}else if(Set.of("FAILED","CANCELLED","OWNER_UNAVAILABLE","OWNER_BUSY","MANAGED","WINDOWS","NO_CANDIDATE").contains(now)){preparing=false;phase="APPLY_REFUSED";}}}
 public void save(String address,String url,String auth){try{ServerDirectory76.save(RemoteService69.root(),address,url,auth);if(state==null)phase="SAVED";}catch(Exception bad){phase="FAILED";error="BOOTSTRAP76_DIRECTORY";}}
 public void forget(String address){try{ServerDirectory76.forget(RemoteService69.root(),address);phase="FORGOTTEN";}catch(Exception bad){phase="FAILED";}}
 public void connect(Runnable callback){if(busy()||!phase.equals("MATCH")||state==null)return;var expected=state;Minecraft mc=Minecraft.getInstance();Path profile=mc.gameDirectory.toPath().toAbsolutePath().normalize();List<Path> loaded=FirstLaunchServer58.loaded();work("CONNECT_CHECK",()->{var fresh=Bootstrap76.inspect(game,endpoint,"1.21.1",expected.offer().neoforge(),cancelled::get);Bootstrap76.same(expected,fresh);if(!Bootstrap76.runtimeMatchesStartup(fresh,profile,loaded,"1.21.1",expected.offer().neoforge(),BootstrapRuntime76.snapshot()))throw new java.io.IOException("BOOTSTRAP76_CHANGED");checkOpen();phase="CONNECTING";mc.execute(()->{if(!cancelled.get()&&mc.getConnection()==null&&mc.level==null)callback.run();});});}
 public void close(){cancelled.set(true);if(preparing&&!armed)RemoteApplyService70.command("CANCEL");}
}
